const item = $input.first().json;
let domain = (item.domain || '').toString().trim().toLowerCase();
domain = domain.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
if (!domain) { throw new Error('Input "domain" is required'); }
let competitors = item.competitors;
if (typeof competitors === 'string') { try { competitors = JSON.parse(competitors); } catch (e) { competitors = competitors.split(','); } }
if (!Array.isArray(competitors)) { throw new Error('Input "competitors" must be an array'); }
competitors = competitors.map(c => (c || '').toString().trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '')).filter(Boolean);
if (competitors.length === 0) { throw new Error('Input "competitors" must be a non-empty array'); }
const location = (item.location || '').toString().trim();
const language = (item.language || '').toString().trim();
const sd = $getWorkflowStaticData('global');
sd.skipped = [];
return [{ json: { domain, competitors, location, language } }];

