const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message.content) || '{}';
let seeds = [];
try { seeds = JSON.parse(raw).seeds || []; } catch (e) { seeds = []; }
const seen = new Set();
const out = [];
for (let s of seeds) { s = (s || '').toString().trim().toLowerCase(); if (s && !seen.has(s)) { seen.add(s); out.push({ json: { seed: s } }); } }
const max = Number($('Vars').first().json.seedCount) || 50;
return out.slice(0, max);

const items = $input.all();
const seeds = $('Seeds Parse').all().map(i => i.json.seed);
const minSearches = Number($('Vars').first().json.minSearches) || 0;
const minCf = Number($('Vars').first().json.commonFactorMin) || 0;
const sd = $getWorkflowStaticData('global'); sd.skipped = sd.skipped || [];
const out = [];
items.forEach((it, idx) => {
  const j = it.json; const data = j && j.data;
  if (!Array.isArray(data)) { sd.skipped.push({ stage: 'expand', key: seeds[idx] != null ? seeds[idx] : idx }); return; }
  for (const r of data) {
    const kw = (r.keyword || '').toString().trim(); if (!kw) continue;
    const searches = Number(r.searches != null ? r.searches : (r.statistics && r.statistics.searches ? r.statistics.searches.current : 0)) || 0;
    const cpc = r.cpc != null ? r.cpc : (r.statistics && r.statistics.cpc ? r.statistics.cpc.current : null);
    const cf = Number(r.common_factor) || 0;
    if (searches < minSearches || cf < minCf) continue;
    out.push({ json: { keyword: kw, searches, cpc: cpc == null ? null : Number(cpc), common_factor: cf, source: 'seed' } });
  }
});
return out;

const items = $input.all();
const sd = $getWorkflowStaticData('global'); sd.skipped = sd.skipped || [];
const out = [];
items.forEach((it, idx) => {
  const j = it.json; const data = j && j.data;
  if (!Array.isArray(data)) { sd.skipped.push({ stage: 'competitor', key: idx }); return; }
  for (const r of data) {
    const kw = (r.keyword || '').toString().trim(); if (!kw) continue;
    const st = r.statistics || {};
    const searches = st.searches ? st.searches.current : (r.searches != null ? r.searches : 0);
    const cpc = st.cpc ? st.cpc.current : (r.cpc != null ? r.cpc : null);
    out.push({ json: { keyword: kw, searches: Number(searches) || 0, cpc: cpc == null ? null : Number(cpc), source: 'competitor' } });
  }
});
return out;

const items = $input.all();
const map = new Map();
for (const it of items) {
  const j = it.json; const kw = (j.keyword || '').toString().trim(); if (!kw) continue;
  const norm = kw.toLowerCase();
  const searches = Number(j.searches) || 0;
  const cpc = j.cpc == null ? null : Number(j.cpc);
  const ex = map.get(norm);
  if (!ex) map.set(norm, { keyword: kw, searches, cpc });
  else { if (searches > ex.searches) ex.searches = searches; if (ex.cpc == null && cpc != null) ex.cpc = cpc; }
}
return Array.from(map.values()).map(v => ({ json: v }));

const items = $input.all();
const cutoff = Number($('Vars').first().json.top50Cutoff) || 50;
const top50 = [];
for (const it of items) {
  const j = it.json; const data = j && j.data;
  if (!Array.isArray(data)) continue;
  for (const r of data) {
    const pos = r.statistics && r.statistics.position ? r.statistics.position.current : null;
    const kw = (r.keyword || '').toString().trim().toLowerCase();
    if (kw && pos != null && pos > 0 && pos <= cutoff) top50.push(kw);
  }
}
return [{ json: { top50: Array.from(new Set(top50)) } }];

const bulk = $('Build Bulk').all().map(i => i.json);
const top50 = new Set(($input.first().json.top50) || []);
const out = [];
for (const b of bulk) {
  const norm = (b.keyword || '').toString().trim().toLowerCase();
  if (!norm) continue;
  if (top50.has(norm)) continue;
  out.push({ json: b });
}
return out;

const items = $input.all().map(i => i.json);
const size = Number($('Vars').first().json.relevanceBatch) || 100;
const chunks = [];
for (let i = 0; i < items.length; i += size) chunks.push(items.slice(i, i + size));
return chunks.map(c => ({ json: { phrases: c.map(x => x.keyword) } }));

const relevant = new Set();
for (const it of $input.all()) {
  const raw = (it.json.choices && it.json.choices[0] && it.json.choices[0].message.content) || '{}';
  try { const arr = JSON.parse(raw).relevant || []; for (const k of arr) relevant.add((k || '').toString().trim().toLowerCase()); } catch (e) {}
}
const gap = $('Hard Filter').all().map(i => i.json);
const seen = new Set();
const out = [];
for (const g of gap) {
  const norm = (g.keyword || '').toString().trim().toLowerCase();
  if (relevant.has(norm) && !seen.has(norm)) { seen.add(norm); out.push({ json: g }); }
}
return out;

const it = $input.first();
const sd = $getWorkflowStaticData('global');
const skipped = sd.skipped || [];
let rowCount = 0;
try { rowCount = $('Map Columns').all().length; } catch (e) {}
const out = { json: { rowCount, skippedCount: skipped.length, skipped } };
if (it && it.binary) out.binary = it.binary;
return [out];

const items = $input.all().map(i => i.json);
const minVol = Number($('Vars').first().json.minOutputSearches) || 0;
const strip = s => (s || '').toString().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[Łł]/g, 'l').toLowerCase();
const hasPL = s => /[ąćęłńóśźż]/i.test(s || '');
const stop = new Set(['sklep','sklepy','internetowy','internetowe','internetowa','online','z','ze','do','na','dla','i','w','meski','meskie','meska','damski','damskie','damska']);
const canon = s => { const t = strip(s).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean).map(w => w.replace(/(y|i|e|ow|a)$/, '')).filter(w => !stop.has(w) && w.length > 1).sort().join(' '); return t || strip(s); };
const groups = new Map();
for (const it of items) {
  const s = Number(it.searches) || 0;
  if (s < minVol) continue;
  const key = canon(it.keyword);
  const cur = groups.get(key);
  if (!cur) { groups.set(key, it); continue; }
  const sc = Number(cur.searches) || 0;
  let better = false;
  if (s > sc) better = true;
  else if (s === sc) {
    if (hasPL(it.keyword) && !hasPL(cur.keyword)) better = true;
    else if (hasPL(it.keyword) === hasPL(cur.keyword) && (it.keyword || '').length < (cur.keyword || '').length) better = true;
  }
  if (better) groups.set(key, it);
}
return Array.from(groups.values()).map(v => ({ json: v }));

const items = $input.all().map(i => i.json);
const vi = $('Validate Input').first().json;
const strip = s => (s || '').toString().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[Łł]/g, 'l').toLowerCase();
const loc = strip(vi.location || '').trim();
const lang = (vi.language || '').toString().toLowerCase().trim();
const comps = (($('Vars').first().json.competitors) || []).map(c => strip(c).split('.')[0]).filter(c => c.length >= 6);
const priceRe = /(cena|cennik|koszt|kosztuj|dofinans|refund|abonament|promocj|rabat|najtan|wycen|oferta|nfz)/;
const infoRe = /(\bjak\b|\bjaka\b|\bjaki\b|\bjakie\b|\bczy\b|\bkiedy\b|\bdlaczego\b|\bczemu\b|\bco to\b|co zrobic|na czym|ile razy|ile trwa|ile dni|objawy|\bdieta\b|\bszanse\b|powodzeni|skutecznosc|jak wyglada|jak przebiega|\bprzebieg\b|przeciwwskazani|\betapy\b|przyczyny|zalecenia|przygotowac|przygotowani|opinie|statystyk|znaczeni|definicj|forum|krok po kroku|w ktorym dniu|domowe sposoby)/;
const CITIES = ['warszawa','krakow','poznan','wroclaw','gdansk','lodz','katowice','szczecin','lublin','bydgoszcz','gdynia','torun','kielce','rzeszow','olsztyn','opole','czestochowa','radom','sosnowiec','gliwice','zabrze','bialystok','jelenia gora','plock','slupsk','walbrzych','bytom','rybnik','tychy','elblag','tarnow','chorzow','kalisz','koszalin','legnica','wloclawek','nysa','nowy sacz'];
const PLW = ['kalendarz','rezerwacj','spotka','termin','wizyt','aplikacj','narzedzi','darmo','abonament','cennik','cena','koszt','firm','biur','klient','obslug','zarzadz','platnosc','przypomnie','faktur','umawia','grafik'];
const ENG = ['appointment','calendar','booking','scheduling','shared','sharing','team ','pricing','doodle','meeting','planner','make ','widget','admin','create','management','reminder','staff','customer','software','account'];
const out = [];
for (const it of items) {
  const kw = (it.keyword || '').toString();
  const n = strip(kw);
  if (comps.some(b => n.includes(b))) continue;
  if (infoRe.test(n) && !priceRe.test(n)) continue;
  if (loc) { const c = CITIES.find(x => n.includes(x)); if (c && !loc.includes(c) && !c.includes(loc)) continue; }
  if (lang.startsWith('pl')) { const hasPL = /[ąćęłńóśźż]/i.test(kw) || PLW.some(w => n.includes(w)); const looksEng = ENG.some(t => n.includes(t.trim())); if (!hasPL && looksEng) continue; }
  out.push({ json: it });
}
return out;

// Mapuje odpowiedz OpenAI web search na pole siteText dla Analyze Domain
const c = $input.first().json?.choices?.[0]?.message?.content || '';
return [{ json: { domain: $('Vars').first().json.domain, title: '', metaDesc: '', detectedCity: '', siteText: c } }];

// Prog min. wolumenu z Vars Extra.minGapSearches (fallback 25): tnie dlugi ogon PRZED Hard Filter i LLM Relevance.
const MIN = Number($('Vars Extra').first().json.minGapSearches) || 25;
return $input.all().filter(it => (Number(it.json.searches) || 0) >= MIN);

// TWARDY FILTR ENCJI: miasta + imiona (GitHub, cache 30 dni + fallback) + adresy/ulice/kody.
const items = $input.all();
const helpers = this.helpers;
const sd = $getWorkflowStaticData('global');
const strip = s => (s || '').toString().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[Łł]/g, 'l').toLowerCase().trim();
const CITIES_URL = 'https://raw.githubusercontent.com/bukowa/polskie-miasta/master/miasta_.json';
const NAMES_URL = 'https://raw.githubusercontent.com/denmats/imiona_polskie/master/imiona_polskie.csv';
const FB_CITIES = ['warszawa','krakow','lodz','wroclaw','poznan','gdansk','szczecin','bydgoszcz','lublin','katowice','bialystok','gdynia','czestochowa','radom','torun','sosnowiec','rzeszow','kielce','gliwice','olsztyn','zabrze','bytom','rybnik','opole','tychy','plock','elblag','walbrzych','wloclawek','tarnow','chorzow','koszalin','kalisz','legnica','slupsk','jaworzno','konin','inowroclaw','lubin','suwalki','gniezno','glogow','leszno','zamosc','przemysl','zakopane','sopot','pruszkow','swidnica','tczew','pila','zgierz','mielec','bedzin','raciborz'];
const FB_NAMES = ['jan','anna','piotr','maria','andrzej','krzysztof','katarzyna','tomasz','magdalena','marcin','agnieszka','pawel','barbara','michal','marek','jakub','adam','jerzy','wojciech','robert','grzegorz','lukasz','kamil','bartosz','filip','rafal','damian','sebastian','mateusz','natalia','aleksandra','weronika','wiktoria','marta','emilia','justyna','karolina','monika','dorota','beata'];
const CITY_EXCLUDE = new Set(['biala','gora','wola','nowe','stare','ruda','kamien','dab','brzeg','debno','kock','lipie','makow','deba','leba','mrocza','slesin','kolo','warta','kozy','sucha','pisz','reda','hel','rabka','wlen','nowa','stara','laziska','serock','biskupiec']);
const NAME_EXCLUDE = new Set(['pola','maja','lena','lana','rena','nela','tola','ina','ala','ola','ewa','iga','mai','sela','lola','nora','rosa','gaja']);
async function get(url) { try { return await helpers.httpRequest({ method: 'GET', url, timeout: 12000 }); } catch (e) { return null; } }
const DAY = 86400000;
let lists = sd.entityLists;
if (!lists || !lists.ts || (Date.now() - lists.ts) > 30 * DAY) {
  let cities = [], names = [];
  let cj = await get(CITIES_URL);
  if (typeof cj === 'string') { try { cj = JSON.parse(cj); } catch (e) { cj = null; } }
  if (Array.isArray(cj)) cities = cj.map(x => strip(x && x.text_simple)).filter(Boolean);
  let nt = await get(NAMES_URL);
  if (typeof nt === 'string') names = nt.split(/\r?\n/).map(strip).filter(w => w && w !== 'imie');
  const ok = cities.length >= 100 && names.length >= 50;
  if (cities.length < 100) cities = FB_CITIES;
  if (names.length < 50) names = FB_NAMES;
  lists = { ts: Date.now(), cities: cities, names: names, src: ok ? 'github' : 'fallback' };
  sd.entityLists = lists;
}
const CITY1 = new Set(), CITY2 = [];
for (const c of lists.cities) { if (!c || c.length < 4 || CITY_EXCLUDE.has(c)) continue; if (c.indexOf(' ') >= 0 || c.indexOf('-') >= 0) CITY2.push(c); else CITY1.add(c); }
const NAMES = new Set();
for (const nm of lists.names) { if (nm && nm.length >= 3 && !NAME_EXCLUDE.has(nm)) NAMES.add(nm); }
const STREET = new Set(['ul','ulica','aleja','aleje','al','os','osiedle','plac','pl','rondo']);
const postal = /\d{2}-\d{3}/;
const out = [];
for (const it of items) {
  const n = strip(it.json.keyword);
  if (postal.test(n)) continue;
  if (CITY2.length && CITY2.some(c => n.indexOf(c) >= 0)) continue;
  const words = n.split(/[^a-z0-9]+/).filter(Boolean);
  if (words.some(w => STREET.has(w) || CITY1.has(w) || NAMES.has(w))) continue;
  out.push(it);
}
return out;
